insert into public.learning_categories(id,slug,name,description,sort_order,is_active) values ('d93dd172-940d-469c-9e2b-126acfc36bff','web-application-security','Web Application Security','Learn how modern web applications work, where trust boundaries exist, and how authentication and authorization failures become real security issues.',0,true);
insert into public.learning_topics(id,category_id,slug,name,description,difficulty,estimated_minutes,sort_order,status,content) values
('10000000-0000-4000-8000-000000000001','d93dd172-940d-469c-9e2b-126acfc36bff','web-application-security-fundamentals','Web Application Security Fundamentals','A practical introduction to web application security: assets, users, trust boundaries, attack surface, and the difference between a bug and a security vulnerability.','Beginner',20,0,'published','{"history":"Web security evolved from simple server-rendered pages into distributed applications with browsers, APIs, databases, CDNs, identity providers, third-party JavaScript, and cloud services. OWASP Top 10:2025 is an awareness baseline rather than a complete security standard; OWASP recommends ASVS when teams need verifiable application-security requirements.","keywords":["web application security","web security fundamentals","application security","web security for beginners","cybersecurity"],"overview":"Web application security is the practice of designing, building, testing, and operating web applications so that untrusted users cannot cross security boundaries they are not authorized to cross. Identify important assets, identify who can influence each request, map trust boundaries, and verify every security-sensitive decision on the server. A web bug becomes a security issue when it lets an untrusted party violate confidentiality, integrity, authentication, authorization, or availability.","defensive":["Use a documented threat model and explicit trust boundaries.","Centralize authentication and authorization decisions where practical.","Deny access by default for protected resources and fail securely.","Validate and normalize security-sensitive input at the point of use.","Log important authentication and authorization failures without leaking secrets.","Use OWASP ASVS when you need a testable security-requirements baseline rather than relying on the Top 10 alone."],"seo_title":"Web Application Security Fundamentals: Beginner Guide | OopsMyPassword","real_world":["OWASP Top 10:2025 puts Broken Access Control at A01 and Authentication Failures at A07, showing how central identity and authorization are to application security.","Modern applications combine multiple trust boundaries: browser state, reverse proxies, application servers, databases, object storage, and third-party services. A security control is useful only if the component making the final decision actually trusts the data it uses."],"references":["https://top10.owasp.org/2025/","https://devguide.owasp.org/en/03-requirements/05-asvs/","https://portswigger.net/web-security/getting-started"],"how_it_works":["Start with the application model: browser or client → web server → application logic → database or internal service.","Map assets and actions: accounts, personal data, administrative functions, files, payments, tokens, and other sensitive operations.","Treat browser-controlled values, cookies, headers, URL parameters, request bodies, and client-side JavaScript as potentially attacker-controlled.","Find the security decision: is this user logged in, can this user edit this record, or is this value safe to pass to another interpreter?","Verify the decision at the trusted server-side boundary. Hiding a button in the browser is not an authorization control."],"seo_description":"Learn web application security fundamentals, attack surface, trust boundaries, security controls, and a practical testing mindset.","what_to_look_for":["List sensitive assets and privileged actions before testing.","Identify every user-controlled input and where it is consumed.","Check whether authentication, authorization, validation, and security-sensitive business rules are enforced server-side.","Compare what the UI allows with what the underlying HTTP endpoints actually accept.","Look for inconsistent security controls between similar endpoints, methods, roles, or application states."]}'),
('10000000-0000-4000-8000-000000000002','d93dd172-940d-469c-9e2b-126acfc36bff','http-requests-responses','HTTP Requests & Responses','Understand HTTP methods, URLs, headers, cookies, status codes, request bodies, and why HTTP is the foundation of practical web security testing.','Beginner',22,1,'published','{"history":"HTTP originated as a simple protocol for transferring hypermedia and has evolved through HTTP/1.1, HTTP/2, and HTTP/3. Its headers, methods, caching behavior, cookies, authentication mechanisms, and proxy ecosystem are fundamental to modern applications.","keywords":["HTTP requests","HTTP responses","HTTP security","web security testing","HTTP headers","Burp Suite basics"],"overview":"HTTP is the language through which browsers and web applications exchange requests and responses. For security testing, read the HTTP message rather than treating a web page as a black box. A request can contain a method, path, query parameters, headers, cookies, and a body. A response can contain a status code, headers, cookies, and content. Small differences often reveal authentication, authorization, caching, validation, or routing behavior.","defensive":["Use HTTPS consistently and configure secure transport correctly.","Parse and validate HTTP messages consistently across front-end and back-end components.","Set appropriate cookie attributes and avoid placing sensitive data in URLs when a safer mechanism is available.","Return appropriate status codes without exposing unnecessary implementation details.","Define explicit cache behavior for sensitive responses and test proxy/CDN behavior.","Use a well-tested framework HTTP stack rather than implementing protocol parsing yourself."],"seo_title":"HTTP Requests & Responses for Web Security | OopsMyPassword","real_world":["MDN describes HTTP as a client-server protocol where clients send requests and servers return responses; understanding that flow is foundational for web debugging and security testing.","Security issues such as request smuggling, cache poisoning, authentication weaknesses, and Host-header problems can arise when different components interpret HTTP messages differently."],"references":["https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview","https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference","https://portswigger.net/web-security/essential-skills"],"how_it_works":["The client sends a request such as GET, POST, PUT, PATCH, or DELETE to a URL.","The request can contain query parameters, headers, cookies, and a body. Treat values supplied by the client as untrusted unless the server independently verifies them.","A server or intermediary processes the request and returns a response with a status code, headers, cookies, and content.","Cookies can make stateless HTTP participate in stateful sessions, so security depends on how session identifiers are generated, transmitted, scoped, and invalidated.","Reverse proxies, CDNs, and caches can introduce additional parsing and trust boundaries, so the same request should not automatically be assumed to mean the same thing at every layer."],"seo_description":"Learn HTTP requests and responses for web security testing: methods, headers, cookies, status codes, parameters, and request flow.","what_to_look_for":["Identify the method, path, query string, Host header, cookies, authorization headers, content type, and body.","Record how status codes and response bodies change when one input changes.","Check which values are reflected, stored, used for routing, used for authorization, or passed to another component.","Compare browser-visible behavior with the underlying request and response.","Pay attention to Set-Cookie attributes such as Secure, HttpOnly, and SameSite."]}'),
('10000000-0000-4000-8000-000000000003','d93dd172-940d-469c-9e2b-126acfc36bff','authentication-and-session-security','Authentication & Session Security','Learn how websites verify identity, maintain sessions, handle passwords and MFA, and where authentication logic can fail.','Beginner',24,2,'published','{"history":"Web authentication progressed from simple HTTP authentication and password forms toward cookie-based sessions, federated identity, MFA, passkeys, and modern identity protocols. The larger the authentication surface becomes, the more important consistent session lifecycle and recovery controls become.","keywords":["web authentication","session security","authentication vulnerabilities","session management","MFA security","login security"],"overview":"Authentication answers who you are; authorization answers what you are allowed to do. Authentication normally involves a credential or factor, a verification step, and then a session mechanism that lets the application recognize subsequent requests. Failures can appear in login, password reset, MFA, remember-me features, session handling, logout, or recovery flows—not only in the main login form.","defensive":["Use HTTPS for authentication and enforce secure transport.","Use a well-tested authentication framework and store passwords using modern password hashing rather than reversible encryption.","Use generic authentication error responses and sensible abuse controls without creating account-enumeration leaks.","Generate unpredictable session identifiers and rotate them after authentication or other sensitive state transitions.","Protect session cookies with appropriate Secure, HttpOnly, and SameSite settings.","Make password reset, MFA, remember-me, and account recovery at least as carefully protected as normal login."],"seo_title":"Web Authentication & Session Security Guide | OopsMyPassword","real_world":["PortSwigger''s current authentication material covers username enumeration, brute-force defenses, MFA logic, password reset, remember-me mechanisms, and other authentication flaws.","OWASP ASVS 5.0 separates authentication and session management into dedicated verification areas, reflecting that proving identity and securely maintaining that identity are related but distinct controls."],"references":["https://portswigger.net/web-security/authentication","https://portswigger.net/web-security/authentication/securing","https://cornucopia.owasp.org/taxonomy/asvs-5.0/07-session-management/02-fundamental-session-management-security"],"how_it_works":["A user submits an authentication attempt, usually over HTTPS.","The server verifies the supplied factor against trusted credential or identity data.","After successful authentication, the application establishes a session using a secure session identifier or another validated mechanism.","Subsequent requests carry the session state, commonly through a cookie, and the server maps it to the authenticated identity.","Sensitive state changes such as login, privilege changes, password changes, and recovery should trigger appropriate session lifecycle controls."],"seo_description":"Learn secure web authentication and session management: login flows, cookies, MFA, password reset, brute-force protection, and common weaknesses.","what_to_look_for":["Check whether invalid and valid usernames produce distinguishable messages, status codes, response sizes, or timing.","Review login rate limiting and whether recovery or password-change endpoints have weaker controls than the main login.","Inspect session cookies for appropriate security attributes and check whether sessions are rotated at important authentication boundaries.","Review logout, password reset, remember-me, MFA, and re-authentication flows as separate attack surfaces.","Look for state-machine flaws where an application grants authenticated functionality before every required verification step is complete."]}'),
('10000000-0000-4000-8000-000000000004','d93dd172-940d-469c-9e2b-126acfc36bff','access-control-authorization','Access Control & Authorization','Learn how web applications decide which users can access which data and perform which actions, including horizontal and vertical privilege boundaries.','Beginner',24,3,'published','{"history":"As web applications moved from simple pages to multi-user systems and APIs, authorization became a major security boundary. OWASP Top 10:2025 lists Broken Access Control as A01. Modern ASVS 5.0 includes dedicated authorization requirements covering general authorization design, operation-level authorization, and other authorization considerations.","keywords":["access control","authorization","IDOR","BOLA","privilege escalation","web security"],"overview":"Access control is the server-side decision about whether an already-identified user is allowed to access a resource or perform an action. A strong authorization model considers identity, role, resource, action, and context. Common failures include horizontal access-control problems where one user can access another user''s data, and vertical privilege escalation where a lower-privileged user reaches administrative functionality.","defensive":["Deny access by default to protected resources.","Enforce authorization server-side at the point where the resource or action is accessed.","Centralize authorization policy where practical so endpoints do not implement contradictory rules.","Bind object access to the authenticated principal and explicit permissions; never trust a client-supplied role or ownership field.","Test horizontal, vertical, and context-dependent authorization paths with negative cases.","Log important authorization failures and review them for abuse patterns."],"seo_title":"Web Access Control & Authorization: IDOR and Privilege Escalation | OopsMyPassword","real_world":["PortSwigger''s access-control material covers vertical and horizontal privilege escalation, IDOR, multi-step processes, URL and method-based controls, and prevention.","OWASP guidance emphasizes explicit authorization checks for each protected resource or action rather than relying on obscurity, client-side controls, or assumptions about how users navigate the application."],"references":["https://top10.owasp.org/2025/","https://portswigger.net/web-security/access-control","https://cornucopia.owasp.org/cards/AZ6"],"how_it_works":["Authentication establishes the identity associated with a request.","The application determines the requested resource and action.","The server evaluates policy using trusted identity and authorization data.","The server allows or denies the operation. The decision must happen at the protected resource or action, not only in the UI.","For object-level access, the authorization check must bind the requested object to the caller''s actual permissions or ownership."],"seo_description":"Learn web access control and authorization, including horizontal and vertical privilege escalation, IDOR/BOLA concepts, and secure authorization design.","what_to_look_for":["Create a matrix of roles, users, resources, and sensitive actions.","Compare the same request using two authorized test accounts with different ownership or privilege levels.","Check direct object references such as user IDs, document IDs, order IDs, filenames, and account identifiers.","Test protected functions through their underlying HTTP requests rather than relying on whether a button is visible.","Review multi-step workflows and alternate HTTP methods for inconsistent authorization enforcement."]}');
insert into public.learning_labs(id,topic_id,title,provider,url,description,sort_order,is_active) values
('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Web Security Academy — Getting Started','PortSwigger','https://portswigger.net/web-security/getting-started','Use the guided Web Security Academy material to learn the basic workflow and practice only inside authorized labs.',0,true),
('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Web Security Academy — Essential Skills','PortSwigger','https://portswigger.net/web-security/essential-skills','Practice reading and manipulating HTTP traffic in PortSwigger''s deliberately vulnerable training environment.',0,true),
('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','Authentication Labs','PortSwigger','https://portswigger.net/web-security/authentication','Choose an Apprentice-level authentication lab and focus on the flawed control, evidence in HTTP traffic, and defensive fix.',0,true),
('20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000004','Access Control Labs','PortSwigger','https://portswigger.net/web-security/access-control','Choose an Apprentice-level access-control lab and compare requests made by users with different privileges or ownership.',0,true);
insert into public.learning_quizzes(id,topic_id,passing_score,max_score,questions) values
('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',15,20,'[["Which statement best describes a web application security trust boundary?",["A place where an untrusted value crosses into a component making a security-sensitive decision","A CSS boundary around a page","A DNS record that points to a server","A browser bookmark"]],["Why is hiding an administrative button in JavaScript not an authorization control?",["The user can still send the underlying request directly to the server","JavaScript cannot render buttons","CSS is always insecure","Browsers ignore hidden elements"]],["Which question should be asked when mapping a sensitive endpoint?",["Who can perform this action and what server-side rule proves it?","What color is the submit button?","Which browser extension is installed?","How many images are on the page?"]],["What does OWASP ASVS provide compared with the OWASP Top 10?",["A more verifiable set of application-security requirements","A list of browser themes","A password wordlist","A replacement for HTTP"]]]'),
('30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002',15,20,'[["Which part of an HTTP request commonly identifies the resource being requested?",["The request target/path","The response status text","The browser window title","The CSS stylesheet"]],["Why are HTTP headers important in security testing?",["They can carry security-relevant metadata such as cookies, authorization, content type, and caching directives","They only control page colors","They are never sent to servers","They replace the request body"]],["What is the security significance of a session cookie?",["It can associate subsequent requests with an authenticated session","It is only used to store images","It guarantees authorization by itself","It makes HTTP stateful at the network layer"]],["Why can proxies and CDNs matter to HTTP security?",["Different components may parse or cache the same request differently","They remove all HTTP headers","They automatically authenticate every user","They prevent all application vulnerabilities"]]]'),
('30000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003',15,20,'[["What is authentication primarily responsible for?",["Verifying a claimed identity","Deciding which database row a user owns","Rendering an HTML button","Choosing a CDN"]],["Why should password reset be tested as part of authentication security?",["It is another path that can change or recover account access","It is unrelated to account security","It only changes page styling","It cannot affect sessions"]],["What is a useful session-management property after successful authentication?",["The application establishes a strong, unpredictable session and handles its lifecycle securely","The browser stores the password in the URL","The session ID is predictable","The user role is trusted from a hidden form field"]],["Which is a meaningful authentication testing signal?",["Different responses reveal whether a username exists","The login page uses a dark theme","The logo is centered","The password field has rounded corners"]]]'),
('30000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000004',15,20,'[["What is authorization responsible for?",["Deciding whether an authenticated principal may perform an action or access a resource","Proving that a password is correct","Rendering the login form","Resolving DNS"]],["What is horizontal privilege escalation?",["Accessing another user''s resources at a similar privilege level","Becoming a site administrator from a normal account","Changing a browser window size","Moving between network switches"]],["Why is IDOR dangerous?",["A user-controlled object reference may let a user access an object they are not authorized to access","It always means SQL injection","It only affects CSS","It automatically encrypts data"]],["Where should authorization be enforced for a protected action?",["On the trusted server-side path that performs the action","Only in client-side JavaScript","Only by hiding the UI element","Only in a robots.txt file"]]]');
